import{_ as e,o as a,c as s,ag as n}from"./chunks/framework.BtkZWVrG.js";const u=JSON.parse('{"title":"SaaS Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"guide/saas-architecture.md","filePath":"guide/saas-architecture.md"}'),r={name:"guide/saas-architecture.md"};function i(o,t,d,l,p,c){return a(),s("div",null,[...t[0]||(t[0]=[n(`<h1 id="saas-architecture" tabindex="-1">SaaS Architecture <a class="header-anchor" href="#saas-architecture" aria-label="Permalink to &quot;SaaS Architecture&quot;">​</a></h1><p>How Luke is deployed as a multi-tenant SaaS: shared clusters for small customers, dedicated clusters for organizations, and a thin control plane that keeps it all coherent.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>This page describes the <strong>target architecture</strong>. Some pieces (control plane, auth gateway, Stripe integration) are not yet built. Status of each component is marked <strong>Built</strong> or <strong>Planned</strong> in the tables below.</p></div><h2 id="the-big-picture" tabindex="-1">The big picture <a class="header-anchor" href="#the-big-picture" aria-label="Permalink to &quot;The big picture&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>                ┌──────────────────────────────┐</span></span>
<span class="line"><span>                │   Supabase  (auth provider)  │</span></span>
<span class="line"><span>                │   - email / password         │</span></span>
<span class="line"><span>                │   - Google / GitHub / FB     │</span></span>
<span class="line"><span>                │   - issues JWT               │</span></span>
<span class="line"><span>                └──────────────┬───────────────┘</span></span>
<span class="line"><span>                               │ JWT</span></span>
<span class="line"><span>                               ▼</span></span>
<span class="line"><span>                ┌──────────────────────────────┐</span></span>
<span class="line"><span>                │      auth-gateway            │</span></span>
<span class="line"><span>                │   - verifies JWT (JWKS)      │</span></span>
<span class="line"><span>                │   - GET /me (UI bootstrap)   │</span></span>
<span class="line"><span>                │   - routes to cluster        │</span></span>
<span class="line"><span>                └──────────────┬───────────────┘</span></span>
<span class="line"><span>                               │</span></span>
<span class="line"><span>            ┌──────────────────┴───────────────────┐</span></span>
<span class="line"><span>            │       Control Plane DB               │</span></span>
<span class="line"><span>            │  • tenant → cluster_url              │</span></span>
<span class="line"><span>            │  • luke_user_profile                 │</span></span>
<span class="line"><span>            │  • billing (stripe_customer_id)      │</span></span>
<span class="line"><span>            └──────────────────┬───────────────────┘</span></span>
<span class="line"><span>                               │</span></span>
<span class="line"><span>       ┌───────────────────────┼──────────────────────┐</span></span>
<span class="line"><span>       ▼                       ▼                      ▼</span></span>
<span class="line"><span>  ┌────────────┐         ┌────────────┐         ┌────────────┐</span></span>
<span class="line"><span>  │  Shared    │         │  acme.luke │         │  bigco.luke│</span></span>
<span class="line"><span>  │  Cluster   │         │  (dedicated│         │  (dedicated│</span></span>
<span class="line"><span>  │            │         │   cluster) │         │   cluster) │</span></span>
<span class="line"><span>  │ CIBSeven   │         │ CIBSeven   │         │ CIBSeven   │</span></span>
<span class="line"><span>  │ + caps     │         │ + caps     │         │ + caps     │</span></span>
<span class="line"><span>  │ + DB       │         │ + DB       │         │ + DB       │</span></span>
<span class="line"><span>  │            │         │            │         │            │</span></span>
<span class="line"><span>  │ N tenants  │         │ 1 tenant   │         │ 1 tenant   │</span></span>
<span class="line"><span>  │ (logical)  │         │            │         │            │</span></span>
<span class="line"><span>  └────────────┘         └────────────┘         └────────────┘</span></span>
<span class="line"><span>     Render                  Render                   AWS</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  Stripe (payments, never in your DB) ──webhooks──► Control Plane</span></span></code></pre></div><p>The architectural insight that makes this clean: <strong>dedicated isn&#39;t a special code path. It&#39;s the same software with <code>tenant_count = 1</code>.</strong></p><p>The multi-tenancy filter in the capabilities service treats both the same way — shared cluster has many <code>tenant_id</code> values, dedicated has one.</p><h2 id="the-four-boundaries" tabindex="-1">The four boundaries <a class="header-anchor" href="#the-four-boundaries" aria-label="Permalink to &quot;The four boundaries&quot;">​</a></h2><h3 id="_1-authentication-—-supabase" tabindex="-1">1. Authentication — Supabase <a class="header-anchor" href="#_1-authentication-—-supabase" aria-label="Permalink to &quot;1. Authentication — Supabase&quot;">​</a></h3><p>Supabase owns <em>who you are</em>: email/password, social provider integration (Google, GitHub, Facebook, Apple), session lifecycle, MFA.</p><table tabindex="0"><thead><tr><th>Property</th><th>Value</th></tr></thead><tbody><tr><td>Status</td><td>Planned</td></tr><tr><td>Hosting</td><td>Supabase Cloud (one project, global)</td></tr><tr><td>What it stores</td><td><code>auth.users</code> (email, password hash, social IDs, refresh tokens)</td></tr><tr><td>What it returns</td><td>JWT with user UUID + email claim</td></tr></tbody></table><p>The Supabase <code>auth.users.id</code> (UUID) becomes the <strong>canonical user ID across every other store</strong> — control plane, CIBSeven, all of it.</p><h3 id="_2-routing-ui-bootstrap-—-auth-gateway" tabindex="-1">2. Routing &amp; UI bootstrap — auth-gateway <a class="header-anchor" href="#_2-routing-ui-bootstrap-—-auth-gateway" aria-label="Permalink to &quot;2. Routing &amp; UI bootstrap — auth-gateway&quot;">​</a></h3><p>The gateway is a small Spring Boot service that sits between the UI and every cluster. It does two jobs:</p><ol><li>Verify the JWT and set identity context (Spring&#39;s <code>oauth2-resource-server</code> + JWKS to Supabase)</li><li>Expose a single <code>GET /me</code> endpoint that returns everything the UI needs to render in one round trip</li></ol><table tabindex="0"><thead><tr><th>Property</th><th>Value</th></tr></thead><tbody><tr><td>Status</td><td>Planned</td></tr><tr><td>Hosting</td><td>Render (single instance)</td></tr><tr><td><code>/me</code> payload</td><td><code>{ user, tenant, cluster_url, capabilities, features, groups }</code></td></tr><tr><td>Routing</td><td>Reads <code>tenant → cluster_url</code> from control plane DB</td></tr></tbody></table><p>The gateway is <strong>not a security boundary</strong> — it&#39;s a convenience for the UI. Each business service still verifies the JWT independently. If someone bypasses the gateway with a valid JWT, every downstream service must still enforce its own rules.</p><h3 id="_3-the-control-plane" tabindex="-1">3. The control plane <a class="header-anchor" href="#_3-the-control-plane" aria-label="Permalink to &quot;3. The control plane&quot;">​</a></h3><p>The control plane is the only piece that exists <em>outside</em> any single cluster. It holds the data that no individual cluster could own on its own.</p><table tabindex="0"><thead><tr><th>Owns</th><th>Why centralized</th></tr></thead><tbody><tr><td><code>tenant → cluster_url</code></td><td>The gateway has to route <em>before</em> any cluster sees the request</td></tr><tr><td>Stripe customer / subscription IDs</td><td>One invoice per customer across all clusters</td></tr><tr><td><code>luke_user_profile</code> (name, prefs, avatar)</td><td>A user is global; clusters are not</td></tr><tr><td>Supabase webhook handler</td><td>Has to live somewhere; new dedicated clusters don&#39;t exist yet at signup</td></tr></tbody></table><table tabindex="0"><thead><tr><th>Property</th><th>Value</th></tr></thead><tbody><tr><td>Status</td><td>Planned</td></tr><tr><td>Hosting</td><td>Render Postgres + Spring Boot (same JAR as gateway, until it grows)</td></tr><tr><td>Tech</td><td>Spring Boot 3.4 + Postgres</td></tr></tbody></table><h3 id="_4-cluster-instances-—-cibseven-capabilities-paired" tabindex="-1">4. Cluster instances — CIBSeven + capabilities, paired <a class="header-anchor" href="#_4-cluster-instances-—-cibseven-capabilities-paired" aria-label="Permalink to &quot;4. Cluster instances — CIBSeven + capabilities, paired&quot;">​</a></h3><p>A &quot;cluster&quot; in Luke = <strong>one CIBSeven instance + one capabilities service + one database, deployed as a unit</strong>. Two flavors:</p><table tabindex="0"><thead><tr><th>Flavor</th><th>Tenants per cluster</th><th>Hosting</th><th>Plans</th></tr></thead><tbody><tr><td><strong>Shared</strong></td><td>Many (logical isolation via <code>tenant_id</code>)</td><td>Render</td><td>Solo $20, Small Org $50</td></tr><tr><td><strong>Dedicated</strong></td><td>One</td><td>Render or AWS</td><td>Organization $199+</td></tr></tbody></table><p>Same JAR, same migrations, same code. The only difference is how many distinct <code>tenant_id</code> values exist in the DB.</p><table tabindex="0"><thead><tr><th>Property</th><th>Status</th></tr></thead><tbody><tr><td>CIBSeven engine</td><td>Built (<a href="./../../core-engine/">core-engine</a>)</td></tr><tr><td>Capabilities service</td><td>Built (<a href="./../../core-engine-capabilities/">core-engine-capabilities</a>)</td></tr><tr><td>Multi-tenant filter</td><td>Built (<code>TenantContext</code>, <code>TenantAwareEntity</code>)</td></tr><tr><td>Registration capability (CIBSeven user/group provisioning)</td><td>Built (<code>RegistrationService</code>)</td></tr></tbody></table><h2 id="where-data-lives" tabindex="-1">Where data lives <a class="header-anchor" href="#where-data-lives" aria-label="Permalink to &quot;Where data lives&quot;">​</a></h2><p>The single most important diagram. Each user fact lives in exactly one place.</p><table tabindex="0"><thead><tr><th>Data</th><th>Where</th><th>Why there</th></tr></thead><tbody><tr><td>Email, password hash, social IDs, sessions, MFA</td><td><strong>Supabase</strong></td><td>They handle the hard security parts</td></tr><tr><td>Canonical user UUID</td><td><strong>Supabase</strong> <code>auth.users.id</code></td><td>Foreign key everywhere else</td></tr><tr><td>Display name, avatar, locale, preferences</td><td><strong>Control plane</strong> <code>luke_user_profile</code></td><td>Global to the platform</td></tr><tr><td>Tenant assignment, subscription tier, billing state</td><td><strong>Control plane</strong></td><td>Survives cluster moves</td></tr><tr><td>Stripe <code>customer_id</code>, <code>subscription_id</code></td><td><strong>Control plane</strong></td><td>One billing relationship per customer</td></tr><tr><td><strong>Card numbers, CVV, payment methods</strong></td><td><strong>Stripe only</strong> — never in your DB</td><td>PCI compliance is huge effort; let Stripe own it</td></tr><tr><td>Capability subscriptions, configs, feature flags</td><td><strong>Cluster</strong> capabilities DB</td><td>Cluster-local product state</td></tr><tr><td>BPMN process state, tasks, history</td><td><strong>Cluster</strong> CIBSeven DB</td><td>Workflow engine needs its own tables</td></tr><tr><td>Workflow users, groups, tenants (for task assignment)</td><td><strong>Cluster</strong> CIBSeven <code>ACT_ID_*</code> tables</td><td>BPMN engine queries these directly</td></tr></tbody></table><h2 id="the-lifecycle-of-a-new-user" tabindex="-1">The lifecycle of a new user <a class="header-anchor" href="#the-lifecycle-of-a-new-user" aria-label="Permalink to &quot;The lifecycle of a new user&quot;">​</a></h2><p>Walking through everything that happens when Sarah signs up for the Solo plan:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1.  Sarah → Consumer UI → &quot;Sign up with Google&quot;</span></span>
<span class="line"><span>2.  Supabase auth flow:</span></span>
<span class="line"><span>       UI redirects to Google → Google auth → back to Supabase</span></span>
<span class="line"><span>       Supabase creates auth.users row, returns JWT to UI</span></span>
<span class="line"><span>3.  Supabase fires webhook: user.created → auth-gateway</span></span>
<span class="line"><span>4.  Gateway creates control plane rows:</span></span>
<span class="line"><span>       luke_user_profile (id = supabase UUID, name = &quot;Sarah&quot;)</span></span>
<span class="line"><span>       Default tenant assigned: tenant_id = sarah-&lt;uuid&gt;</span></span>
<span class="line"><span>       cluster_url = the shared cluster</span></span>
<span class="line"><span>5.  Gateway calls cluster&#39;s RegistrationService:</span></span>
<span class="line"><span>       POST /api/registration/tenants    → creates tenant in CIBSeven</span></span>
<span class="line"><span>       POST /api/registration/tenants/{id}/users → creates Sarah in CIBSeven</span></span>
<span class="line"><span>6.  UI receives JWT, calls GET /me on gateway:</span></span>
<span class="line"><span>       Returns user + tenant + cluster_url + capabilities + features</span></span>
<span class="line"><span>7.  UI now knows to make API calls to cluster_url for everything else</span></span></code></pre></div><p>When Sarah upgrades to a $199 Org plan and wants dedicated:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1.  Sarah clicks &quot;Upgrade&quot; in Billing → POST /api/billing/checkout (gateway)</span></span>
<span class="line"><span>2.  Gateway creates Stripe Checkout session → returns URL</span></span>
<span class="line"><span>3.  Sarah pays on Stripe&#39;s hosted page (your servers never see the card)</span></span>
<span class="line"><span>4.  Stripe fires customer.subscription.created webhook → gateway</span></span>
<span class="line"><span>5.  Gateway updates control plane:</span></span>
<span class="line"><span>       billing.stripe_subscription_id = &quot;sub_xxx&quot;</span></span>
<span class="line"><span>       billing.tier = &quot;ORG&quot;</span></span>
<span class="line"><span>6.  Provisioning trigger (manual at first, automated later):</span></span>
<span class="line"><span>       New Render service: CIBSeven + caps + DB → returns cluster_url</span></span>
<span class="line"><span>7.  Migrate Sarah&#39;s tenant data from shared cluster → new dedicated cluster</span></span>
<span class="line"><span>8.  Update control plane: tenant.cluster_url = new dedicated URL</span></span>
<span class="line"><span>9.  Next UI request: gateway routes Sarah to the new cluster</span></span></code></pre></div><h2 id="pricing-tiers-in-code" tabindex="-1">Pricing tiers, in code <a class="header-anchor" href="#pricing-tiers-in-code" aria-label="Permalink to &quot;Pricing tiers, in code&quot;">​</a></h2><p>Existing enum: <code>Capability.Tier</code> = FREE / BASIC / PRO / ENTERPRISE.</p><p>Mapping to the SaaS tiers:</p><table tabindex="0"><thead><tr><th>Plan</th><th>Price</th><th>Tenants per cluster</th><th>Max users</th><th>Tier value</th><th>Cluster</th></tr></thead><tbody><tr><td>Solo</td><td>$20 / mo</td><td>shared</td><td>1</td><td>BASIC</td><td>shared</td></tr><tr><td>Small Org</td><td>$50 / mo</td><td>shared</td><td>1</td><td>PRO</td><td>shared</td></tr><tr><td>Organization</td><td>$199 / mo</td><td>1 (dedicated)</td><td>20</td><td>ENTERPRISE</td><td>dedicated</td></tr></tbody></table><p>Enforcement:</p><ul><li><strong>Tier-to-capability mapping</strong> in <code>SubscriptionCheckFilter</code> — already partly there</li><li><strong><code>max_users</code></strong> column on subscription (or new <code>Plan</code> entity) — planned</li><li><strong><code>cluster_id</code></strong> column on tenant — planned, lives in control plane</li></ul><h2 id="four-decisions-to-lock-in-before-scaffolding" tabindex="-1">Four decisions to lock in before scaffolding <a class="header-anchor" href="#four-decisions-to-lock-in-before-scaffolding" aria-label="Permalink to &quot;Four decisions to lock in before scaffolding&quot;">​</a></h2><ol><li><p><strong>Same service or separate for gateway + control plane?</strong> Start with one Spring Boot service sharing one DB. Split when it grows.</p></li><li><p><strong>DNS strategy?</strong> Subdomains per dedicated cluster (<code>acme.luke.com</code>) feel more premium and make routing trivial. Single domain with internal routing is simpler to operate but less brandable.</p></li><li><p><strong>Provisioning automation?</strong> Manual via Render dashboard for the first 10–20 dedicated customers. Automate via Render API once it stops being fun at 11 PM.</p></li><li><p><strong>Which DB owns user identity?</strong> Already answered: Supabase owns auth, control plane owns profile, CIBSeven owns workflow identity, all keyed by the same UUID.</p></li></ol><h2 id="what-s-built-today" tabindex="-1">What&#39;s built today <a class="header-anchor" href="#what-s-built-today" aria-label="Permalink to &quot;What&#39;s built today&quot;">​</a></h2><p>If you&#39;re walking the codebase, here&#39;s what already exists for this story:</p><table tabindex="0"><thead><tr><th>Theme park metaphor</th><th>Code</th></tr></thead><tbody><tr><td>List of rides</td><td><a href="https://github.com/" target="_blank" rel="noreferrer"><code>Capability.java</code></a> — registry of capabilities</td></tr><tr><td>Season passes</td><td><a href="https://github.com/" target="_blank" rel="noreferrer"><code>CapabilitySubscription.java</code></a> — per-tenant subscriptions</td></tr><tr><td>Per-park preferences</td><td><a href="https://github.com/" target="_blank" rel="noreferrer"><code>CapabilityConfig.java</code></a> — tenant config</td></tr><tr><td>Sub-features on/off</td><td><a href="https://github.com/" target="_blank" rel="noreferrer"><code>CapabilityFeature.java</code></a> — feature flags</td></tr><tr><td>Multi-tenancy plumbing</td><td><code>TenantAwareEntity</code> + <code>TenantContext</code> + <code>TenantInterceptor</code></td></tr><tr><td>Gate at every ride</td><td><a href="https://github.com/" target="_blank" rel="noreferrer"><code>SubscriptionCheckFilter.java</code></a></td></tr><tr><td>Adding to staff list</td><td><a href="https://github.com/" target="_blank" rel="noreferrer"><code>RegistrationService.java</code></a> (CIBSeven proxy)</td></tr></tbody></table><h2 id="what-s-left-to-build" tabindex="-1">What&#39;s left to build <a class="header-anchor" href="#what-s-left-to-build" aria-label="Permalink to &quot;What&#39;s left to build&quot;">​</a></h2><p>The shortest path to the full architecture:</p><table tabindex="0"><thead><tr><th>#</th><th>Component</th><th>Effort</th><th>Unlocks</th></tr></thead><tbody><tr><td>1</td><td>Control plane schema (<code>luke_user_profile</code>, <code>luke_tenant_billing</code>, <code>luke_tenant_cluster</code>)</td><td>Small</td><td>Identity model</td></tr><tr><td>2</td><td>Supabase webhook handler</td><td>Small</td><td>New user → control plane row</td></tr><tr><td>3</td><td>JWT verification filter (replace <code>X-Tenant-Id</code> header trust)</td><td>Small</td><td>Real authentication</td></tr><tr><td>4</td><td><code>GET /me</code> endpoint</td><td>Small</td><td>UI bootstrap</td></tr><tr><td>5</td><td>Stripe Checkout + webhook</td><td>Medium</td><td>Billing</td></tr><tr><td>6</td><td>Cluster routing (lookup <code>cluster_url</code>, proxy or hint)</td><td>Medium</td><td>Multi-cluster</td></tr><tr><td>7</td><td>Render automation script for dedicated provisioning</td><td>Medium</td><td>Self-serve upgrades</td></tr></tbody></table><p>Each step is independently shippable. The minimum viable SaaS = steps 1–4 running on a single shared cluster.</p>`,49)])])}const b=e(r,[["render",i]]);export{u as __pageData,b as default};
